import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a = list(map(int, data[:6]))

    b = [0] * 10
    for x in a:
        if 1 <= x <= 9:
            b[x] += 1

    y = 0
    no = 0

    for i in range(1, 10):
        if b[i] == 4:
            for j in range(1, 10):
                if b[j] == 2:
                    y += 1
        elif b[i] > 4:
            if b[i] == 6:
                y += 1
        else:
            no += 1

    if no == 9:
        print("Alien")
    else:
        if y == 1:
            print("Elephant")
        else:
            print("Bear")

if __name__ == "__main__":
    main()

